#include <stdio.h>
#include <string.h>
#include <stdlib.h>

char* rightPadSpace(const char* s, long long width) {
    long long len = strlen(s);
    if (len >= width) {
        char* result = malloc(len + 1);
        if (!result) return NULL;
        strcpy(result, s);
        return result;
    }

    long long spaces_needed = width - len;
    char* result = malloc(width + 1);
    if (!result) return NULL;

    strcpy(result, s);
    for (long long i = 0; i < spaces_needed; i = i + 1) {
        result[len + i] = ' ';
    }
    result[width] = '\0';
    return result;
}

void free_result(char* ptr) {
    if (ptr) free(ptr);
}

int main() {
    // Test 1: Normal case
    char* r1 = rightPadSpace("hello", 10);
    printf("'%s'\n", r1);
    free_result(r1);

    // Test 2: Already at width
    char* r2 = rightPadSpace("world", 5);
    printf("'%s'\n", r2);
    free_result(r2);

    // Test 3: Empty string
    char* r3 = rightPadSpace("", 6);
    printf("'%s'\n", r3);
    free_result(r3);

    // Test 4: Width zero
    char* r4 = rightPadSpace("test", 0);
    printf("'%s'\n", r4);
    free_result(r4);

    // Test 5: Single character
    char* r5 = rightPadSpace("A", 5);
    printf("'%s'\n", r5);
    free_result(r5);

    // Test 6: Long string
    char* r6 = rightPadSpace("abcdefghij", 15);
    printf("'%s'\n", r6);
    free_result(r6);

    // Test 7: Exact match
    char* r7 = rightPadSpace("exact", 5);
    printf("'%s'\n", r7);
    free_result(r7);

    return 0;
}

