import java.util.*;

public class Solution {
    public static String rightPadSpace(String s, int width) {
        int n = s.length();
        if (n >= width) {
            return s;
        }
        StringBuilder result = new StringBuilder(s);
        int spacesNeeded = width - n;
        for (int i = 0; i < spacesNeeded; i++) {
            result.append(' ');
        }
        return result.toString();
    }

    public static void main(String[] args) {
        // Test case 1: normal padding
        System.out.println(rightPadSpace("hello", 10));

        // Test case 2: already at width
        System.out.println(rightPadSpace("world", 5));

        // Test case 3: empty string
        System.out.println(rightPadSpace("", 3));

        // Test case 4: width zero
        System.out.println(rightPadSpace("test", 0));

        // Test case 5: width negative (should return original)
        System.out.println(rightPadSpace("abc", -2));

        // Test case 6: single character
        System.out.println(rightPadSpace("x", 5));

        // Test case 7: string longer than width
        System.out.println(rightPadSpace("longstring", 4));
    }
}
